insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'gk_pe_v1'
from (values
('116.12.b.1.A',2,'Which movement is done by pushing off one foot and landing on the same foot?','["hopping", "rolling", "sliding", "sitting"]'::jsonb,0,'A hop starts and ends on the same foot.','original'),
('116.12.b.1.A',2,'Which movement uses a step and a quick bounce, one foot after the other, like a horse?','["floating", "galloping", "crawling", "spinning"]'::jsonb,1,'A gallop has a step-and-leap rhythm.','original'),
('116.12.b.1.A',2,'To stay balanced while skipping, you should...','["close your eyes", "hold your breath", "keep your eyes up and your arms loose", "stare at your feet only"]'::jsonb,2,'Looking ahead helps balance.','original'),
('116.12.b.1.B',2,'Which is a way to jump in place?','["stand on your hands", "lie down", "walk backward", "bend your knees and push up with both feet"]'::jsonb,3,'Jumping uses bent knees and both feet.','original'),
('116.12.b.1.B',2,'When you jump side to side, you move...','["left and right", "only forward", "up and down only", "in a circle only"]'::jsonb,0,'Side to side means left and right.','original'),
('116.12.b.1.C',2,'Tracking a ball with your eyes means you...','["turn around", "watch it as it moves", "close your eyes", "look away"]'::jsonb,1,'Visual tracking follows moving objects.','original'),
('116.12.b.1.C',2,'Doing two skills in order, like hop then jump, is called...','["sleeping", "sitting", "sequencing", "resting"]'::jsonb,2,'A sequence is skills done in order.','original'),
('116.12.b.1.D',2,'Rolling your body sideways on a mat is called a...','["jump rope", "cartwheel", "dribble", "log roll"]'::jsonb,3,'A log roll is a sideways roll.','original'),
('116.12.b.1.D',2,'Spinning slowly versus quickly changes the...','["speed of the turn", "number of fingers", "size of the room", "color of the mat"]'::jsonb,0,'Speed is how fast you move.','original'),
('116.12.b.2.A',2,'Which body part is a base of support when you stand on one foot?','["your ear", "your foot", "your elbow", "your nose"]'::jsonb,1,'The foot supports your weight.','original'),
('116.12.b.2.A',2,'Which position gives you the widest, steadiest base?','["leaning far back", "standing with feet together on tiptoe", "feet apart and knees bent", "standing on one toe"]'::jsonb,2,'A wide base is steadier.','original'),
('116.12.b.2.B',2,'Curling your body means you...','["run fast", "jump high", "stretch tall", "round your body into a small shape"]'::jsonb,3,'Curling makes a rounded shape.','original'),
('116.12.b.2.B',2,'Stretching your arms up high helps you...','["reach and lengthen your body", "curl up small", "hide", "fall down"]'::jsonb,0,'Stretching lengthens muscles.','original'),
('116.12.b.3.A',2,'Which foot should be forward when you throw underhand?','["neither foot", "the foot opposite your throwing hand", "both feet", "the same foot as your throwing hand"]'::jsonb,1,'Opposite foot forward gives balance.','original'),
('116.12.b.3.A',3,'When tossing a ball to yourself, you should toss it...','["to the ceiling fan", "straight at a window", "gently upward in front of you", "behind your back hard"]'::jsonb,2,'Gentle tosses are easier to catch.','original'),
('116.12.b.3.B',2,'To catch something thrown to you, where should your eyes stay?','["on the clock", "on the floor", "on the ceiling", "on the object coming toward you"]'::jsonb,3,'Watching the object helps you catch it.','original'),
('116.12.b.3.B',2,'When catching, your hands should be...','["ready and open in front of your body", "in your pockets", "over your eyes", "behind your back"]'::jsonb,0,'Open hands are ready to catch.','original'),
('116.12.b.3.C',2,'When dribbling with one hand, you push the ball with...','["your foot", "your fingertips", "your elbow", "your head"]'::jsonb,1,'Fingertips control the ball.','original'),
('116.12.b.3.D',2,'To tap a ball with your foot, you use the...','["top of your head", "toe only, as hard as you can", "inside of your foot", "heel only"]'::jsonb,2,'The inside of the foot gives control.','original'),
('116.12.b.3.E',2,'To kick a ball that is standing still, you should...','["pick it up", "jump in the air", "sit on it", "step with one foot and kick with the other"]'::jsonb,3,'Plant one foot and swing the other.','original'),
('116.12.b.3.F',2,'To volley a light balloon to yourself, you gently...','["hit it upward with your hands", "kick it hard", "throw it down", "hold it still"]'::jsonb,0,'Volleying keeps it in the air.','original'),
('116.12.b.3.G',2,'A good way to strike a lightweight object is to use...','["your head", "your hand or a short paddle", "a chair", "a heavy bat"]'::jsonb,1,'Light objects need light tools.','original'),
('116.12.b.3.H',2,'When you jump rope, you swing the rope over your head and...','["sit on it", "throw it", "jump over it", "crawl under it"]'::jsonb,2,'The rope must pass under your feet.','original'),
('116.12.b.3.I',2,'When two people swing a long rope, they should...','["tie it up", "let go", "jump on it", "swing it back and forth together"]'::jsonb,3,'Partners swing in rhythm.','original'),
('116.12.b.4.A',2,'Your personal space is...','["the space around your body", "the whole gym", "a closet", "a classmate''s space"]'::jsonb,0,'Personal space is your own area.','original'),
('116.12.b.4.A',2,'General space is...','["a locker", "the open area where everyone can move", "the space inside your pocket", "a tiny box"]'::jsonb,1,'General space is shared.','original'),
('116.12.b.4.B',2,'A pathway can be...','["red or blue", "hot or cold", "straight, curvy, or zigzag", "loud or quiet"]'::jsonb,2,'Pathways are the lines you travel.','original'),
('116.12.b.4.B',2,'Moving low to the floor is a change in...','["volume", "color", "taste", "level"]'::jsonb,3,'Levels are high, medium or low.','original'),
('116.12.b.4.C',2,'Moving fast then slow shows a change in...','["speed", "taste", "temperature", "color"]'::jsonb,0,'Contrast uses different speeds.','original'),
('116.12.b.4.C',2,'Moving forward then backward changes your...','["weight", "direction", "height", "age"]'::jsonb,1,'Direction is the way you move.','original'),
('116.12.b.5',2,'When you dance to music, you should move with the...','["clock", "door", "beat", "window"]'::jsonb,2,'Rhythm follows the beat.','original'),
('116.12.b.5',2,'A steady beat is like a...','["song with no sound", "lost shoe", "storm", "heartbeat that repeats"]'::jsonb,3,'A beat repeats evenly.','original'),
('116.12.b.6.A',2,'In a chasing game, which skill means moving quickly away from the person chasing you?','["fleeing", "dribbling", "catching", "volleying"]'::jsonb,0,'Fleeing is moving away to avoid being tagged.','original'),
('116.12.b.6.A',2,'Dodging means you...','["stand still", "quickly change direction to avoid being tagged", "sit down", "jump rope"]'::jsonb,1,'Dodge by moving sideways quickly.','original'),
('116.12.b.6.A',2,'While playing a tag game, you should keep your hands to yourself and stay...','["inches from others", "under tables", "in safe space away from others", "on the walls"]'::jsonb,2,'Safe space prevents bumping.','original'),
('116.12.b.6.B',2,'When your teacher shows a skill, you should...','["do something else", "leave", "ignore it", "watch and try it the same way"]'::jsonb,3,'Following directions helps you improve.','original'),
('116.12.b.6.C',2,'Which is a safe practice in class?','["follow the rules and listen to directions", "throw balls at people", "take equipment without asking", "run into friends"]'::jsonb,0,'Safety means following rules.','original'),
('116.12.b.8.A',2,'When you run, your heart beats...','["not at all", "faster", "slower", "backward"]'::jsonb,1,'Exercise speeds the heart.','original'),
('116.12.b.8.A',2,'After you exercise, your breathing is...','["stopped", "slower", "faster", "gone"]'::jsonb,2,'Lungs work harder with exercise.','original'),
('116.12.b.8.B',2,'Why is daily active play important?','["it makes you tired forever", "it hurts your heart", "it stops growth", "it keeps your body healthy and strong"]'::jsonb,3,'Play builds strength.','original'),
('116.12.b.8.C',2,'Which activity helps your fitness?','["jumping jacks", "sleeping all day", "sitting in a car", "watching TV"]'::jsonb,0,'Exercise builds fitness.','original'),
('116.12.b.9.A',2,'Setting a goal means you...','["ignore your coach", "decide something you want to work toward", "forget your plan", "quit"]'::jsonb,1,'A goal is something you aim for.','original'),
('116.12.b.9.B',2,'You can see if you are getting better at hopping by...','["guessing", "sleeping", "counting how many hops you can do", "hiding"]'::jsonb,2,'Counting measures progress.','original'),
('116.12.b.10.A',2,'Why do we eat a variety of foods?','["to lose our teeth", "to make us sleepy", "to stop growing", "to give our body energy"]'::jsonb,3,'Different foods give energy and nutrients.','original'),
('116.12.b.10.B',2,'The best drink to have during exercise is...','["water", "soda", "coffee", "candy"]'::jsonb,0,'Water hydrates your body.','original'),
('116.12.b.11.A',2,'What is the best footwear for playing in P.E.?','["slippers", "sneakers", "boots with heels", "flip flops"]'::jsonb,1,'Sneakers protect feet.','original'),
('116.12.b.11.A',2,'The best clothes for P.E. are...','["a costume", "a winter coat", "loose and comfortable", "tight and stiff"]'::jsonb,2,'Comfortable clothes help movement.','original'),
('116.12.b.11.B',2,'When you cross the street, you should...','["run across", "close your eyes", "play in the road", "look both ways and hold a grown-up''s hand"]'::jsonb,3,'Pedestrian safety means looking.','original'),
('116.12.b.11.B',2,'When riding a bike, you should always wear a...','["helmet", "scarf", "mask", "hat"]'::jsonb,0,'Helmets protect your head.','original'),
('116.12.b.11.B',2,'On a sunny day you should protect your skin with...','["snow", "sunscreen", "oil", "water"]'::jsonb,1,'Sunscreen blocks harmful rays.','original'),
('116.12.b.12.A',2,'If you push a friend in line, a consequence could be that...','["nothing ever happens", "you get a trophy", "your friend gets hurt or you lose a turn", "you win a prize"]'::jsonb,2,'Actions have results.','original'),
('116.12.b.12.B',2,'Respecting differences means you...','["laugh at mistakes", "make fun of others", "ignore people", "kindly accept that everyone is different"]'::jsonb,3,'Respect treats others kindly.','original'),
('116.12.b.12.C',2,'If you feel angry, it is good to...','["name the feeling and tell a teacher", "hit someone", "break equipment", "run away from class"]'::jsonb,0,'Naming feelings helps.','original'),
('116.12.b.13.A',2,'Showing respect to a teammate means...','["calling names", "using kind words and taking turns", "ignoring them", "pushing"]'::jsonb,1,'Respect and cooperation help teams.','original'),
('116.12.b.13.B',2,'If you are upset, an appropriate way to tell the teacher is to...','["throw a ball", "cry loudly forever", "use your words calmly", "yell"]'::jsonb,2,'Calm words get help.','original'),
('116.12.b.14',2,'When something is hard, perseverance means you...','["blame others", "hide", "quit right away", "keep trying"]'::jsonb,3,'Perseverance is not giving up.','original'),
('116.12.b.14',2,'If you miss the ball, a good response is to...','["try again", "walk off", "throw the ball away", "cry and quit"]'::jsonb,0,'Trying again shows grit.','original'),
('116.12.b.15',2,'When a friend gives you a tip kindly, you should...','["argue", "say thank you and try it", "ignore it", "run away"]'::jsonb,1,'Accepting feedback helps you learn.','original'),
('116.12.b.15',2,'A kind way to help a classmate improve is to say...','["That was awful.", "Give up.", "Nice try! Try bending your knees more.", "You are bad."]'::jsonb,2,'Constructive feedback is kind and helpful.','original'),
('116.12.b.16.A',2,'How often should kids be active?','["once a year", "never", "once a month", "every day"]'::jsonb,3,'Daily activity builds health.','original'),
('116.12.b.16.B',2,'Which activity can be fun for exercise?','["dancing", "sleeping", "sitting still", "watching TV"]'::jsonb,0,'Dancing is active and enjoyable.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Physical Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
